def solve(n, edges):
    from collections import defaultdict

    def find(parent, i):
        if parent[i] == i:
            return i
        return find(parent, parent[i])

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

    parent = list(range(n))
    rank = [0] * n

    for u, v in edges:
        union(parent, rank, u, v)

    components = set()
    for i in range(n):
        components.add(find(parent, i))

    return len(components)

