    dist = [[float('inf')] * n for _ in range(n)]
    for u, v, w in edges:
        dist[u][v] = w

    # Set the distance from a node to itself as 0
    for i in range(n):
        dist[i][i] = 0

    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Check if s and t are the same
    if s == t:
        return 0

    # If the distance from s to t is still infinity, it's not reachable
    if dist[s][t] == float('inf'):
        return -1

    return int(dist[s][t])

