def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = [{v: w for v, _, w in e} for e in edges + [(i, 0) for i in range(n) if (i, i, 0) not in edges]]
    dist = [float('inf')] * n
    dist[s] = 0

    def dijkstra():
        nonlocal dist
        q = deque([s])
        while q:
            u = q.popleft()
            for v, w in graph[u].items():
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    q.append(v)

    while True:
        prev_dist = dist[:]
        dijkstra()
        if prev_dist == dist:
            break

    return dist[t] if dist[t] != float('inf') else -1

