def solve(n, edges):
    from collections import defaultdict

    graph = defaultdict(set)
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    visited = [False] * n
    components = 0

    def propagate(node):
        if visited[node]:
            return
        visited[node] = True
        for neighbor in graph[node]:
            propagate(neighbor)

    for node in range(n):
        if not visited[node]:
            components += 1
            propagate(node)

    return components
