def solve(nums, target):
    def binary_search(nums, target, find_first):
        lo, hi = 0, len(nums) - 1
        idx = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:
                idx = mid
                if find_first:
                    hi = mid - 1
