def solve(n, edges):
    adjacency_list = [[] for _ in range(n)]
    for u, v in edges:
        adjacency_list[u].append(v)
        adjacency_list[v].append(u)

    def bfs(start):
        visited = set()
        queue = [start]
        while queue:
            curr = queue.pop(0)
            if curr in visited:
                continue
            visited.add(curr)
            for neighbor in adjacency_list[curr]:
                if neighbor not in visited:
                    queue.append(neighbor)
        return visited

    components = 0
    for i in range(n):
        if i not in adjacency_list[i] and i not in any(neighbors for neighbors in adjacency_list):
            components += 1
        elif i not in any(neighbors for neighbors in adjacency_list):
            components += 1
            bfs(i)

    return components

